function () {
  // The volunteer update link (/update/?t=…) carries a personal token: GA4 gets the address without it.
  var u = new URL(location.href);
  if (/^\/update\/?$/.test(u.pathname)) u.searchParams.delete('t');
  return u.toString();
}

function () {
  // A page opened from /update/?t=… : the referrer without the token.
  var r = document.referrer;
  try { var u = new URL(r); if (/^\/update\/?$/.test(u.pathname)) { u.searchParams.delete('t'); r = u.toString(); } } catch (e) {}
  return r;
}
